=Aşağıdaki metinden Türkçe 5 kısa çoktan seçmeli soru üret. Her seçenek 2-6 kelimelik kısa açıklama içersin, tek harf yazma. Sadece şu JSON formatını döndür:
{"questions":[{"question":"Kısa soru?","options":["A: Kısa şık 1","B: Kısa şık 2","C: Kısa şık 3","D: Kısa şık 4"],"correct_answer":"A: Kısa şık 1"}]}

Metin: {{ $json.body.text }}

parameters.jsCode:
const rawInput = $input.first().json;
const webhookBody = $('Webhook Generate Quiz').first().json.body || {};

// Ollama yanıtını kök dizindeki "content" dahil tüm olası alanlardan al
let rawText =
  rawInput?.content ||
  rawInput?.message?.content ||
  rawInput?.output ||
  rawInput?.text ||
  rawInput?.response ||
  (typeof rawInput === 'string' ? rawInput : JSON.stringify(rawInput));

// Eğer rawText hala obje ise string'e çevir
if (typeof rawText === 'object') {
  rawText = JSON.stringify(rawText);
}

// Markdown kod bloklarını temizle ve ilk { ile son } arasını al
rawText = String(rawText).replace(/```json/gi, '').replace(/```/g, '').trim();
const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) {
  rawText = rawText.slice(firstBrace, lastBrace + 1);
}

let parsed;
try {
  parsed = JSON.parse(rawText);
  // Eğer iç içe string olarak sarılmışsa bir kez daha parse et
  if (typeof parsed?.content === 'string') {
    parsed = JSON.parse(parsed.content);
  }
} catch (err) {
  throw new Error(`JSON_PARSE_ERROR: Model gecerli JSON uretmedi. Ham cikti: ${rawText.slice(0, 200)}`);
}

const validatedData = $('Validate Quiz Schema').first().json;
const mongoResult = $input.first().json;

const clientQuestions = validatedData.questions.map(q => ({
  id: q.id,
  question: q.question,
  options: q.options
}));

return [
  {
    json: {
      quiz_id: mongoResult._id || mongoResult.insertedId || null,
      title: validatedData.title,
      total_questions: clientQuestions.length,
      questions: clientQuestions
    }
  }
];
